-- ============================================================
-- Schema for Rares's AI Agent services
-- learning-path-agent | hr-interview-agent | technical-interview-agent
-- ============================================================

-- Learning paths generated by learning-path-agent
-- One row per user (upserted on new CV analysis)
CREATE TABLE IF NOT EXISTS learning_paths (
    user_id         TEXT PRIMARY KEY,
    target_role     TEXT NOT NULL,
    title           TEXT NOT NULL,
    estimated_weeks INT  NOT NULL,
    plan_data       JSONB NOT NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Interview sessions (HR and Technical)
-- One row per session (session_id is the WebSocket session UUID)
CREATE TABLE IF NOT EXISTS interview_sessions (
    id           TEXT PRIMARY KEY,
    user_id      TEXT NOT NULL,
    type         TEXT NOT NULL CHECK (type IN ('HR', 'Technical')),
    score        INT,
    feedback     TEXT,
    transcript   TEXT,
    completed_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_interview_sessions_user_id
    ON interview_sessions (user_id);

-- Quiz attempts (reserved for future quiz feature in learning-path-agent)
CREATE TABLE IF NOT EXISTS quiz_attempts (
    id          SERIAL PRIMARY KEY,
    user_id     TEXT NOT NULL,
    module_id   TEXT NOT NULL,
    answers     JSONB NOT NULL,
    score       INT,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_quiz_attempts_user_id
    ON quiz_attempts (user_id);
